function validate([nums1, nums2, k]) {
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 100000) return 'nums1 needs 1 to 10^5 values.';
  if (!Array.isArray(nums2) || nums2.length < 1 || nums2.length > 100000) return 'nums2 needs 1 to 10^5 values.';
  if (nums1.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each nums1 value is an integer from 1 to 10^6.';
  if (nums2.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each nums2 value is an integer from 1 to 10^6.';
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is an integer from 1 to 1000.';
  return null;
}

