function numberOfPairs(nums1, nums2, k) {
  let maxQuotient = 0;
  for (const value of nums1) {
    maxQuotient = Math.max(maxQuotient, Math.floor(value / k));
  }
  const quotientCount = new Array(maxQuotient + 1).fill(0);
  for (const value of nums1) {
    if (value % k === 0) {
      quotientCount[value / k]++;
    }
  }

  const divisorCount = new Map();
  for (const value of nums2) {
    divisorCount.set(value, (divisorCount.get(value) || 0) + 1);
  }

  let pairs = 0;
  for (const [divisor, times] of divisorCount) {
    let matches = 0;
    for (let multiple = divisor; multiple <= maxQuotient; multiple += divisor) {
      matches += quotientCount[multiple];
    }
    pairs += matches * times;
  }
  return pairs;
}

