function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const k = int(1, 4);
    const nums1 = Array.from({ length: int(1, 7) }, () => int(1, 40));
    const nums2 = Array.from({ length: int(1, 7) }, () => int(1, 10));
    return [nums1, nums2, k];
  }
  const mode = int(0, 2);
  if (mode === 0) {
    // Long multiples walks: k = 1, many small divisors, values up to 10^6.
    const nums1 = Array.from({ length: 2000 }, () => int(1, 1000000));
    const nums2 = Array.from({ length: 2000 }, () => int(1, 2000));
    return [nums1, nums2, 1];
  }
  if (mode === 1) {
    // Many matches: nums1 values are k times numbers with lots of divisors.
    const k = int(1, 1000);
    const limit = Math.floor(1000000 / k);
    const nums1 = Array.from({ length: 2000 }, () => {
      const base = [1, 2, 6, 12, 24, 60, 120, 360, 720][int(0, 8)];
      const top = Math.max(1, Math.floor(limit / base));
      return Math.min(1000000, k * base * int(1, top));
    });
    const nums2 = Array.from({ length: 2000 }, () => int(1, 30));
    return [nums1, nums2, k];
  }
  // Mixed: half of nums1 are multiples of k, and most divisors are small.
  const k = int(1, 1000);
  const nums1 = Array.from({ length: 2000 }, () => rand() < 0.5 ? k * int(1, Math.floor(1000000 / k)) : int(1, 1000000));
  const nums2 = Array.from({ length: 2000 }, () => rand() < 0.8 ? int(1, 100) : int(1, 1000000));
  return [nums1, nums2, k];
}
